/**
 * scripts/compile-contract.js
 * ---------------------------
 * Compiles contracts/AccessPass.sol with solc-js (no Hardhat, no Foundry;
 * this is a Vite app, we are not dragging in a whole framework) and writes
 * src/blockchain/artifact.js containing the ABI + bytecode.
 *
 * The generated file is marked AUTO-GENERATED and is regenerated on every
 * `npm run dev` / `npm run build` via the predev/prebuild scripts. Never
 * hand-edit the generated ABI/bytecode, edit the .sol and recompile.
 *
 * Why evmVersion "paris"? Solidity >= 0.8.20 defaults to Shanghai, which
 * emits PUSH0 opcodes. Paris avoids PUSH0, so the bytecode runs on both
 * Paris-style and Shanghai-style chains, which is the safest bet for BOT
 * Chain whose exact EVM version we do not control.
 */

import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import solc from "solc";

const require = createRequire(import.meta.url);

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), "..");
const CONTRACT_PATH = "contracts/AccessPass.sol";
const CONTRACT_NAME = "AccessPass";
const OUTPUT_PATH = path.join(ROOT, "src/blockchain/artifact.js");

// Read the contract source once.
const sourcePath = path.join(ROOT, CONTRACT_PATH);
const source = fs.readFileSync(sourcePath, "utf8");

/**
 * solc-js import resolver. solc has no filesystem awareness, so we hand it
 * file contents on demand. @openzeppelin/contracts resolves through
 * node_modules; anything else is treated as a relative local import.
 */
function findImports(importPath) {
  if (importPath.startsWith("@openzeppelin/")) {
    try {
      const resolved = require.resolve(importPath, {
        paths: [path.join(ROOT, "node_modules")],
      });
      return { contents: fs.readFileSync(resolved, "utf8") };
    } catch (err) {
      return { error: `Cannot resolve import "${importPath}". Did you run npm install?` };
    }
  }
  // Local relative imports (unused today, but future-proof and free).
  try {
    const resolved = path.resolve(path.dirname(sourcePath), importPath);
    return { contents: fs.readFileSync(resolved, "utf8") };
  } catch {
    return { error: `Unknown import "${importPath}"` };
  }
}

// Build the solc standard JSON input.
const input = {
  language: "Solidity",
  sources: {
    [CONTRACT_PATH]: { content: source },
  },
  settings: {
    optimizer: { enabled: true, runs: 200 },
    evmVersion: "paris",
    outputSelection: {
      "*": {
        "*": ["abi", "evm.bytecode.object"],
      },
    },
  },
};

const output = JSON.parse(solc.compile(JSON.stringify(input), { import: findImports }));

// Surface compile errors loudly instead of writing a broken artifact.
const errors = (output.errors || []).filter((e) => e.severity === "error");
if (errors.length > 0) {
  console.error("\nSolidity compilation failed:\n");
  for (const err of errors) {
    console.error(`  ${err.formattedMessage || err.message}\n`);
  }
  process.exit(1);
}

const contract = output.contracts[CONTRACT_PATH][CONTRACT_NAME];
if (!contract) {
  console.error(`Contract "${CONTRACT_NAME}" not found in compiler output.`);
  process.exit(1);
}

// Serialize the artifact as an ES module the frontend can import directly.
const abi = contract.abi;
const bytecode = `0x${contract.evm.bytecode.object}`;

const artifact = `// AUTO-GENERATED FILE - DO NOT EDIT BY HAND.
// Generated by scripts/compile-contract.js from ${CONTRACT_PATH}
// (solc ${output.compilerVersion || "?"}). Recompile with: npm run compile:contract
//
// Regenerated automatically on every dev/build, so any manual tweaks here
// will be cheerfully overwritten. Edit the Solidity instead.

export const accessPassAbi = ${JSON.stringify(abi, null, 2)};

export const accessPassBytecode = ${JSON.stringify(bytecode)};

export const accessPassArtifact = {
  abi: accessPassAbi,
  bytecode: accessPassBytecode,
};

export default accessPassArtifact;
`;

fs.mkdirSync(path.dirname(OUTPUT_PATH), { recursive: true });
fs.writeFileSync(OUTPUT_PATH, artifact);

const kb = (bytecode.length / 2 - 1) / 1024;
console.log(`${CONTRACT_NAME} compiled successfully (${output.compilerVersion})`);
console.log(`   Bytecode size : ${kb.toFixed(2)} KB`);
console.log(`   ABI entries   : ${abi.length}`);
console.log(`   Artifact      : ${path.relative(ROOT, OUTPUT_PATH)}`);
